<?phpnamespace app\store\controller;use app\store\model\Order as OrderModel;use app\store\model\RechargeLog as RechargeLogModel;use app\store\model\PaybillLog as PaybillLogModel;use app\store\model\Device as DeviceModel;use think\facade\View;/** * 统计数据 */class Statistics extends Controller{	public function index(string $star='',string $end='')    {        //获取今天的时间戳        $data = [            'star' => strtotime(date('Y-m-d') . ' 00:00:00'),//今天的起始时间戳            'end' => strtotime(date('Y-m-d') . ' 23:59:59'),//今天的结束时间戳        ];        if(!empty($star) and !empty($end)){            $data = [                'star' => strtotime($star . ' 00:00:00'),//指定日期起始时间戳                'end' => strtotime($end . ' 23:59:59'),//指定日期的结束时间戳            ];        }		$count = array();		$count['order'] = OrderModel::getDateCount($data);	//订单统计		$count['recharge'] = RechargeLogModel::getDateCount($data);	//充值统计        $count['paybill'] = PaybillLogModel::getDateCount($data);	//买单统计		return View::fetch('index', compact('count','star','end'));    }        /**     * 打印     */     public function prints(string $star,string $end)     {         //获取今天的时间戳        $data = [            'star' => strtotime(date('Y-m-d') . ' 00:00:00'),//今天的起始时间戳            'end' => strtotime(date('Y-m-d') . ' 23:59:59'),//今天的结束时间戳        ];        if(!empty($star) and !empty($end)){            $data = [                'star' => strtotime($star . ' 00:00:00'),//指定日期起始时间戳                'end' => strtotime($end . ' 23:59:59'),//指定日期的结束时间戳            ];        }		$count = array();		$count['order'] = OrderModel::getDateCount($data);	//订单统计		$count['recharge'] = RechargeLogModel::getDateCount($data);	//充值统计		$count['paybill'] = PaybillLogModel::getDateCount($data);	//买单统计        $count['star'] = $star;        $count['end'] = $end;        if (DeviceModel::print($count,4)) {            return $this->renderSuccess('操作成功');        }        return $this->renderError('操作失败');     }}